// Land navigation drills on the Camp Ripley 1:25,000 map: plot the point, read the grid,
// and shoot an azimuth. Targets are generated by the app (never the course answer keys).
// Routes: #/landnav (menu), #/landnav/plot, #/landnav/read, #/landnav/azimuth.
(function () {
  var G = BWC.Geo;
  var MAP = null, PROJ = null, map = null;
  var PTS = { right: 3, dailyCap: 30 };

  function U() { return BWC.UI; }
  function app() { return document.getElementById('app'); }

  function loadMap() {
    if (MAP) return Promise.resolve();
    return fetch('maps/ripley/map.json').then(function (r) { return r.json(); }).then(function (m) {
      MAP = m;
      PROJ = G.mapProjection(m.width, m.height, m.corners, m.zone);
    });
  }

  // Leaflet loads only when a drill opens, so the rest of the app stays light.
  function loadLeaflet() {
    if (window.L) return Promise.resolve();
    return new Promise(function (resolve, reject) {
      var css = document.createElement('link');
      css.rel = 'stylesheet';
      css.href = 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css';
      document.head.appendChild(css);
      var s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js';
      s.onload = resolve;
      s.onerror = reject;
      document.head.appendChild(s);
    });
  }

  // Native map pixel <-> Leaflet position.
  function ll(x, y) { return map.unproject([x, y], MAP.zmax); }
  function px(latlng) { var p = map.project(latlng, MAP.zmax); return { x: p.x, y: p.y }; }
  function utmToLL(u) { var p = PROJ.toPixel(u.e, u.n); return ll(p.x, p.y); }

  function makeMap(el) {
    if (map) { map.remove(); map = null; }
    map = L.map(el, { crs: L.CRS.Simple, minZoom: 1, maxZoom: MAP.zmax + 2, zoomSnap: 0.5, attributionControl: false });
    var bounds = L.latLngBounds(ll(0, MAP.height), ll(MAP.width, 0));
    L.tileLayer('maps/ripley/{z}/{x}/{y}.jpg', { tileSize: MAP.tile, maxNativeZoom: MAP.zmax, maxZoom: MAP.zmax + 2, noWrap: true, bounds: bounds }).addTo(map);
    map.setMaxBounds(bounds.pad(0.05));
    return map;
  }

  // A random point inside the play area (away from the legend and margins).
  function randomPoint() {
    var a = MAP.playArea;
    var x = (a[0] + Math.random() * (a[2] - a[0])) * MAP.width;
    var y = (a[1] + Math.random() * (a[3] - a[1])) * MAP.height;
    return PROJ.toUTM(x, y);
  }

  function grid8(u) { var m = PROJ.mgrs(u.e, u.n, 8); return m.sq + ' ' + m.e + ' ' + m.n; }

  function earnedToday() {
    var t = BWC.Progress.today();
    return U().S.ledger.filter(function (e) { return e.kind === 'landnav' && toDay(e.at) === t; }).reduce(function (s, e) { return s + e.pts; }, 0);
  }
  function toDay(ms) { var d = new Date(ms || Date.now()); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }

  function record(drill, ok, extra) {
    var pts = ok && earnedToday() + PTS.right <= PTS.dailyCap ? PTS.right : 0;
    return U().award([Object.assign({ kind: 'landnav', pts: pts, ref: drill, ok: ok }, extra || {})]).then(function () { return pts; });
  }

  function stats(drill) {
    var list = U().S.ledger.filter(function (e) { return e.kind === 'landnav' && e.ref === drill; });
    var ok = list.filter(function (e) { return e.ok; }).length;
    return { n: list.length, ok: ok, pct: list.length ? Math.round(ok / list.length * 100) : null };
  }

  // ---------- menu ----------

  var DRILLS = [
    { id: 'plot', name: 'Plot the point', how: 'Given an 8-digit grid, tap that spot on the map. Scored by how many meters off you are.' },
    { id: 'read', name: 'Read the grid', how: 'A point is marked. Give its 8-digit grid.' },
    { id: 'azimuth', name: 'Shoot an azimuth', how: 'Measure the grid azimuth and distance from point A to point B, using the on-screen protractor.' }
  ];

  function viewMenu() {
    var u = U();
    app().innerHTML = u.header('Land nav drills', '#/activities') +
      '<div class="banner"><div class="grow"><div class="eyebrow">Camp Ripley 1:25,000</div><div class="big" style="font-size:30px">Map, grid, azimuth.</div>' +
      '<div class="small" style="font-weight:700">Grid zone 15T, 100 km square UM. Drill points are generated by the app, not course points.</div></div>' + u.icon('compass', 56, 1.8) + '</div>' +
      DRILLS.map(function (d) {
        var s = stats(d.id);
        return '<a class="card roster-card" href="#/landnav/' + d.id + '"><div class="row"><h2 class="grow">' + u.esc(d.name) + '</h2>' +
          (s.n ? '<span class="chip' + (s.pct >= 80 ? ' good' : '') + '">' + s.ok + '/' + s.n + ' right</span>' : '') + '</div><p class="muted">' + u.esc(d.how) + '</p></a>';
      }).join('') +
      '<p class="muted small">' + PTS.right + ' points per correct drill, up to ' + PTS.dailyCap + ' land nav points a day. Study the method in the Land Navigation topic (TC 3-25.26).</p>';
  }

  // ---------- shared drill frame ----------

  function frame(title, prompt, controls) {
    var u = U();
    app().innerHTML = '<div class="row"><a class="btn small ghost" href="#/landnav" aria-label="Back">' + u.icon('back', 18) + '</a><h1 class="grow">' + u.esc(title) + '</h1></div>' +
      '<div class="card ln-prompt">' + prompt + '</div>' +
      '<div id="ln-map" class="ln-map" role="application" aria-label="Camp Ripley map"></div>' +
      '<div class="card">' + controls + '<div id="ln-result"></div></div>';
  }

  function start(fn) {
    var u = U();
    app().innerHTML = u.header('Land nav', '#/landnav') + '<div class="card"><p class="muted">Loading map…</p></div>';
    Promise.all([loadMap(), loadLeaflet()]).then(fn).catch(function () {
      app().innerHTML = u.header('Land nav', '#/landnav') + '<div class="card"><p>The map could not load. Check your connection and try again.</p></div>';
    });
  }

  function marker(latlng, cls, label) {
    return L.marker(latlng, { icon: L.divIcon({ className: 'ln-pin ' + cls, html: label ? '<span>' + label + '</span>' : '', iconSize: [22, 22], iconAnchor: [11, 11] }), keyboard: false }).addTo(map);
  }

  function result(html, ok) {
    document.getElementById('ln-result').innerHTML = '<div class="ln-result ' + (ok ? 'good' : 'bad') + '">' + html + '</div>' +
      '<button type="button" class="btn" id="ln-next">Next drill</button>';
  }

  // ---------- plot the point ----------

  function viewPlot() {
    start(function () {
      var u = U();
      var target = randomPoint();
      var g = grid8(target);
      frame('Plot the point', '<div class="muted small">Plot this grid</div><div class="ln-grid">15T ' + u.esc(g) + '</div><div class="muted small">Zoom in and tap where it is. Tap again to move your mark.</div>',
        '<button type="button" class="btn block" id="ln-check" disabled>Check my plot</button>');
      makeMap(document.getElementById('ln-map'));
      var c = PROJ.toPixel(target.e, target.n);
      // Start zoomed out around the general area (within a few km), like unfolding the map.
      map.setView(ll(c.x + (Math.random() - 0.5) * 900, c.y + (Math.random() - 0.5) * 900), 2);
      var mine = null, done = false;
      map.on('click', function (e) {
        if (done) return;
        if (mine) mine.setLatLng(e.latlng); else mine = marker(e.latlng, 'mine');
        document.getElementById('ln-check').disabled = false;
      });
      document.getElementById('ln-check').addEventListener('click', function () {
        if (!mine || done) return;
        done = true;
        var p = px(mine.getLatLng());
        var at = PROJ.toUTM(p.x, p.y);
        var err = G.distance(at, target);
        var ok = err <= 50;
        var t = utmToLL(target);
        marker(t, 'target');
        L.polyline([mine.getLatLng(), t], { color: ok ? '#22c55e' : '#ef4444', weight: 3, dashArray: '6 6' }).addTo(map);
        map.fitBounds(L.latLngBounds([mine.getLatLng(), t]).pad(1.5), { maxZoom: MAP.zmax });
        record('plot', ok, { err: Math.round(err) }).then(function (pts) {
          result('<strong>' + Math.round(err) + ' m off.</strong> ' + (err <= 10 ? 'Dead on.' : ok ? 'Within 50 m: a GO.' : 'More than 50 m: NO-GO.') +
            '<div class="small">You plotted ' + u.esc(grid8(at)) + '. Target ' + u.esc(g) + '.' + (pts ? ' +' + pts + ' points' : '') + '</div>', ok);
          document.getElementById('ln-next').addEventListener('click', viewPlot);
        });
      });
    });
  }

  // ---------- read the grid ----------

  function viewRead() {
    start(function () {
      var u = U();
      var target = randomPoint();
      frame('Read the grid', '<div class="muted small">Give the 8-digit grid of the marked point (red).</div><div class="muted small">Read right, then up. 100 km square letters are optional.</div>',
        '<label class="field" for="ln-answer">Your grid</label><input class="input mono" id="ln-answer" inputmode="text" autocomplete="off" placeholder="UM 1234 5678">' +
        '<button type="button" class="btn block" id="ln-check">Check</button>');
      makeMap(document.getElementById('ln-map'));
      var t = utmToLL(target);
      marker(t, 'target');
      map.setView(t, 4);
      var done = false;
      document.getElementById('ln-check').addEventListener('click', function () {
        if (done) return;
        var raw = document.getElementById('ln-answer').value;
        var p = PROJ.parse(raw);
        if (!p || p.digits !== 8) { u.toast('Enter an 8-digit grid, e.g. UM 1234 5678'); return; }
        done = true;
        // Correct when each axis is within one 10 m step of the true square.
        var truth = PROJ.mgrs(target.e, target.n, 8);
        var mine = PROJ.mgrs(p.e, p.n, 8);
        var de = Math.abs(parseInt(mine.e, 10) - parseInt(truth.e, 10)), dn = Math.abs(parseInt(mine.n, 10) - parseInt(truth.n, 10));
        var ok = mine.sq === truth.sq && de <= 1 && dn <= 1;
        var err = G.distance(p, target);
        marker(utmToLL(p), 'mine');
        record('read', ok, { err: Math.round(err) }).then(function (pts) {
          result('<strong>' + (ok ? 'GO.' : 'NO-GO.') + '</strong> The grid is <span class="mono">' + u.esc(truth.sq + ' ' + truth.e + ' ' + truth.n) + '</span>.' +
            '<div class="small">Yours lands ' + (err >= 1000 ? (err / 1000).toFixed(1) + ' km' : Math.round(err) + ' m') + ' away.' + (!ok && de > 50 && dn > 50 ? ' Check that you read right (easting) before up (northing).' : '') + (pts ? ' +' + pts + ' points' : '') + '</div>', ok);
          document.getElementById('ln-next').addEventListener('click', viewRead);
        });
      });
    });
  }

  // ---------- azimuth and distance ----------

  function protractor(center, radiusPx) {
    // Drawn in map pixels so it scales with zoom; grid north is straight up on this map.
    var c = px(center);
    var group = L.layerGroup().addTo(map);
    L.circle(center, { radius: radiusPx / Math.pow(2, MAP.zmax), color: '#111', weight: 1.5, fill: true, fillOpacity: 0.08 }).addTo(group);
    for (var d = 0; d < 360; d += 10) {
      var r0 = d % 30 === 0 ? 0.78 : 0.88;
      var a = d * Math.PI / 180;
      var p0 = ll(c.x + Math.sin(a) * radiusPx * r0, c.y - Math.cos(a) * radiusPx * r0);
      var p1 = ll(c.x + Math.sin(a) * radiusPx, c.y - Math.cos(a) * radiusPx);
      L.polyline([p0, p1], { color: '#111', weight: d % 30 === 0 ? 2 : 1 }).addTo(group);
      if (d % 30 === 0) {
        L.marker(ll(c.x + Math.sin(a) * radiusPx * 0.66, c.y - Math.cos(a) * radiusPx * 0.66), {
          icon: L.divIcon({ className: 'ln-deg', html: String(d), iconSize: [30, 16], iconAnchor: [15, 8] }), interactive: false
        }).addTo(group);
      }
    }
    return group;
  }

  function viewAzimuth() {
    start(function () {
      var u = U();
      var a = randomPoint(), b;
      do { b = randomPoint(); } while (G.distance(a, b) < 800 || G.distance(a, b) > 3000);
      var az = G.azimuth(a, b), dist = G.distance(a, b);
      frame('Shoot an azimuth', '<div class="muted small">From <strong>A</strong> to <strong>B</strong>: give the grid azimuth (degrees) and distance (meters).</div>' +
        '<div class="muted small">The protractor is centered on A; grid north is straight up. One grid square is 1,000 m.</div>',
        '<div class="row wrap"><label class="field grow">Grid azimuth (°)<input class="input mono" id="ln-az" inputmode="numeric" placeholder="0–359"></label>' +
        '<label class="field grow">Distance (m)<input class="input mono" id="ln-dist" inputmode="numeric" placeholder="e.g. 1450"></label></div>' +
        '<button type="button" class="btn block" id="ln-check">Check</button>');
      makeMap(document.getElementById('ln-map'));
      var A = utmToLL(a), B = utmToLL(b);
      marker(A, 'pt', 'A');
      marker(B, 'pt', 'B');
      var radius = Math.max(220, (G.distance(a, b) / 4.4) * 0.6);
      protractor(A, radius);
      map.fitBounds(L.latLngBounds([A, B]).pad(0.6), { maxZoom: MAP.zmax });
      var done = false;
      document.getElementById('ln-check').addEventListener('click', function () {
        if (done) return;
        var myAz = parseFloat(document.getElementById('ln-az').value), myDist = parseFloat(document.getElementById('ln-dist').value);
        if (isNaN(myAz) || myAz < 0 || myAz >= 360) { u.toast('Enter an azimuth from 0 to 359.'); return; }
        done = true;
        var azErr = Math.abs(((myAz - az + 540) % 360) - 180);
        var distErr = isNaN(myDist) ? null : Math.abs(myDist - dist) / dist;
        var ok = azErr <= 3 && (distErr == null || distErr <= 0.1);
        L.polyline([A, B], { color: ok ? '#22c55e' : '#ef4444', weight: 3 }).addTo(map);
        record('azimuth', ok, { err: Math.round(azErr) }).then(function (pts) {
          result('<strong>' + (ok ? 'GO.' : 'NO-GO.') + '</strong> Grid azimuth <span class="mono">' + Math.round(az) + '°</span>, distance <span class="mono">' + Math.round(dist).toLocaleString() + ' m</span>.' +
            '<div class="small">You were ' + Math.round(azErr) + '° off' + (distErr == null ? '' : ' and ' + Math.round(distErr * 100) + '% off on distance') +
            '. GO is within 3° and 10%. Convert to a magnetic azimuth with the G-M angle in the map\'s declination diagram.' + (pts ? ' +' + pts + ' points' : '') + '</div>', ok);
          document.getElementById('ln-next').addEventListener('click', viewAzimuth);
        });
      });
    });
  }

  function stop() { if (map) { map.remove(); map = null; } }

  function view(step) {
    if (step === 'plot') return viewPlot();
    if (step === 'read') return viewRead();
    if (step === 'azimuth') return viewAzimuth();
    return viewMenu();
  }

  BWC.LandNav = {
    view: view, stop: stop,
    // For automated checks: the live map and its projection.
    _test: function () { return { map: map, proj: PROJ, ll: ll }; }
  };
})();
